// Turns each received email into an entry of the Notion "Boîte mail" database
// (Notion field names stay in French: they must match the database columns)
const s = (v) => (v == null ? '' : String(v)).trim();
const rt = (v) => ({ rich_text: [{ text: { content: s(v).slice(0, 1900) } }] });
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let de = typeof j.from === 'string' ? j.from : (j.from?.text || j.from?.value?.[0]?.address || '');
  const m = de.match(/[\w.+-]+@[\w-]+(\.[\w-]+)+/);
  const corps = s(j.textPlain || j.text || s(j.textHtml || j.html).replace(/<[^>]+>/g, ' ')).replace(/\n{3,}/g, '\n\n');
  const pj = Object.keys(item.binary || {}).map((k) => item.binary[k].fileName).filter(Boolean).join(', ');
  const date = j.date ? new Date(j.date) : new Date();
  const props = {
    'Objet': { title: [{ text: { content: s(j.subject || '(no subject)').slice(0, 200) } }] },
    'De': rt(de),
    'Reçu le': { date: { start: date.toISOString() } },
    'Contenu': rt(corps),
    'Message-ID': rt(j.messageId || j['message-id'] || ''),
  };
  if (m) props['Email expéditeur'] = { email: m[0].toLowerCase() };
  if (pj) props['Pièces jointes'] = rt(pj);
  out.push({ json: { body: { parent: { database_id: '41c615ef3da181a883b2e1161a4a26d0' }, properties: props } } });
}
return out;
